                    category: { type: Type.STRING },
                  },
                  required: ['original', 'encrypted', 'rule', 'category']
              }
            }
          }
      });

      const response = await retryWithBackoff<GenerateContentResponse>(operation);
      if (response.text) return JSON.parse(cleanJson(response.text));
      return [];
  } catch (error) {
      console.error("Cipher Error:", error);
      throw error;
  }
}

import React, { Component, ReactNode } from 'react';
import { createRoot } from 'react-dom/client';
import App from './App';

interface ErrorBoundaryProps {
  children?: ReactNode;
}

interface ErrorBoundaryState {
  hasError: boolean;
  error: Error | null;
}

class ErrorBoundary extends Component<ErrorBoundaryProps, ErrorBoundaryState> {
  constructor(props: ErrorBoundaryProps) {
    super(props);
    this.state = { hasError: false, error: null };
  }

  static getDerivedStateFromError(error: Error): ErrorBoundaryState {
    return { hasError: true, error };
  }

  render() {
    if (this.state.hasError) {
      return (
        <div style={{
          padding: '2rem',
          color: '#f87171',
          backgroundColor: '#0f172a',
          height: '100vh',
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          justifyContent: 'center',
          fontFamily: 'sans-serif',
          textAlign: 'center'
        }}>
          <h1 style={{fontSize: '2rem', marginBottom: '1rem'}}>Algo deu errado / Something went wrong</h1>
          <p style={{maxWidth: '600px', color: '#cbd5e1'}}>
            {this.state.error?.message}
          </p>
          <button 
            onClick={() => window.location.reload()}
            style={{
              marginTop: '1rem',
              padding: '0.5rem 1rem',
              backgroundColor: '#475569',
              color: 'white',
              border: 'none',
              borderRadius: '0.5rem',
              cursor: 'pointer'
            }}
          >
            Tentar Novamente / Reload
          </button>
        </div>
      );
    }

    return this.props.children; 
  }
}

