               <h2 className="text-2xl font-bold text-red-400 mb-2">{t.quotaMsg}</h2>
               <button 
                  onClick={handleChangeKey}
                  className="bg-red-600 hover:bg-red-500 text-white font-bold py-3 px-8 rounded-full transition-colors mt-4"
              >
                  {t.changeKey}
              </button>
          </div>
        )
