    if (cached) {
        console.log("Ladder: Cached Validation Hit");
        return cached;
    }

    try {
        const ai = getAI();
        const model = 'gemini-2.5-flash';
        const lang = getLanguage();

        // STRICT PROMPT FIX
        // We explicitly tell the AI to reject the target word if it's not immediately connected to current.
        const prompt = `Context: Word Ladder Game. Current: "${current}". Target: "${target}". Input: "${guess}".
        Task: Is "${guess}" a valid next step?
        Rules:
        1. "${guess}" must be logically related to "${current}".
        2. CRITICAL: If "${guess}" is exactly "${target}", it is INVALID unless "${current}" is extremely close to "${target}" (Prevent skipping steps). If jump is too big, valid=false, message="Too big of a jump!".
        3. Lang:${lang}.
        JSON:{isValid,message,emoji,proximity(0-100)}`;

        const operation = () => ai.models.generateContent({
          model,
          contents: prompt,
          config: {
            responseMimeType: 'application/json',
            responseSchema: {
              type: Type.OBJECT,
              properties: {
                isValid: { type: Type.BOOLEAN },
                message: { type: Type.STRING },
                emoji: { type: Type.STRING },
                proximity: { type: Type.NUMBER },
              },
              required: ['isValid', 'message']
            }
          }
        });

        const response = await retryWithBackoff<GenerateContentResponse>(operation);
        if (response.text) {
            const data = JSON.parse(cleanJson(response.text));
            // Cache the result
            saveCache(LADDER_CACHE_KEY, cacheKey, data);
            return data;
        }
        return { isValid: false, message: "Error" };
    } catch (error) {
        console.error("Ladder Validation Error:", error);
        throw error;
    }
};

