import React, { useState, useEffect, useRef } from 'react';
import { DilemmaScenario } from '../types';
import { generateDilemmaBatch } from '../services/geminiService';

const DilemmaGame: React.FC = () => {
  const [scenario, setScenario] = useState<DilemmaScenario | null>(null);
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<'A' | 'B' | null>(null);
  const [quotaError, setQuotaError] = useState(false);

  // Queue System
  const [queue, setQueue] = useState<DilemmaScenario[]>([]);
  const queueRef = useRef<DilemmaScenario[]>([]);

  // Localization
  const isPt = typeof navigator !== 'undefined' ? navigator.language.startsWith('pt') : true;
  const t = {
      title: isPt ? "Dilema Absurdo" : "Absurd Dilemma",
      subtitle: isPt ? "O que você faria nessa situação?" : "What would you do in this situation?",
      loading: isPt ? "A IA está criando um caos moral..." : "AI is creating moral chaos...",
      next: isPt ? "Próximo Dilema" : "Next Dilemma",
      error: isPt ? "Falha ao carregar." : "Failed to load.",
      quotaMsg: isPt ? "Limite diário da API atingido!" : "Daily API quota exceeded!"
  };

  useEffect(() => {
    queueRef.current = queue;
  }, [queue]);

  const loadScenario = async () => {
    setLoading(true);
    setResult(null);
    setQuotaError(false);

    // 1. Check Queue
    if (queueRef.current.length > 0) {
        const next = queueRef.current[0];
        setScenario(next);
        setQueue(prev => prev.slice(1));
        setLoading(false);
        return;
    }

    // 2. Fetch Batch
    try {
        const batch = await generateDilemmaBatch();
        if (batch && batch.length > 0) {
            setScenario(batch[0]);
            setQueue(batch.slice(1));
        } else {
             // Retry? Just generic error for now
        }
    } catch (e: any) {
        if (e.name === 'QuotaExceededError') {
            setQuotaError(true);
        } else {
            console.error(e);
        }
    }
    setLoading(false);
  };

  useEffect(() => {
    loadScenario();
  }, []);

  const handleChoice = (choice: 'A' | 'B') => {
    setResult(choice);
  };

  if (quotaError) {
      return (
        <div className="flex flex-col items-center justify-center min-h-[60vh] max-w-md mx-auto p-8 animate-fade-in text-center">
             <div className="text-6xl mb-4">🛑</div>
             <h2 className="text-2xl font-bold text-red-400 mb-2">{t.quotaMsg}</h2>
        </div>
      )
  }

  return (
    <div className="flex flex-col items-center justify-center min-h-full max-w-4xl mx-auto p-4 animate-fade-in">
        <div className="text-center mb-8">
            <h2 className="text-3xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-pink-500 to-rose-500">
            {t.title}
            </h2>
            <p className="text-slate-400 text-sm mt-1">{t.subtitle}</p>
        </div>

        {loading ? (
            <div className="flex flex-col items-center space-y-4">
                <div className="w-16 h-16 border-4 border-pink-500 border-t-transparent rounded-full animate-spin"></div>
                <p className="text-pink-300 animate-pulse text-lg">{t.loading}</p>
            </div>
        ) : scenario ? (
            <div className="w-full flex flex-col items-center gap-6">

                <div className="bg-slate-800 p-6 rounded-2xl border border-slate-700 shadow-xl max-w-2xl w-full text-center">
                    <h3 className="text-2xl font-bold text-white mb-2">{scenario.title}</h3>
                    <p className="text-slate-300 text-lg leading-relaxed">{scenario.description}</p>
                </div>

                <div className="grid md:grid-cols-2 gap-6 w-full mt-4">
                    {/* Option A */}
                    <div 
                        onClick={() => !result && handleChoice('A')}
                        className={`group relative p-8 rounded-2xl border-2 cursor-pointer transition-all duration-300 transform hover:scale-[1.02] flex flex-col justify-between min-h-[250px]
                        ${result === 'A' ? 'border-pink-500 bg-pink-500/10' : result === 'B' ? 'border-slate-700 opacity-50 bg-slate-800' : 'border-slate-600 bg-slate-800 hover:border-pink-400 hover:shadow-pink-500/20'}
                        `}
                    >
                        <div className="absolute top-4 left-4 text-4xl font-black text-slate-700 group-hover:text-pink-500/30 transition-colors">A</div>
                        <p className="text-xl font-medium text-center text-white z-10">{scenario.optionA}</p>

                        {result === 'A' && (
                            <div className="mt-4 pt-4 border-t border-pink-500/30 animate-fade-in">
                                <p className="text-pink-300 text-sm italic">"{scenario.consequenceA}"</p>
                            </div>
                        )}
                    </div>

                    {/* Option B */}
                    <div 
                        onClick={() => !result && handleChoice('B')}
                        className={`group relative p-8 rounded-2xl border-2 cursor-pointer transition-all duration-300 transform hover:scale-[1.02] flex flex-col justify-between min-h-[250px]
                        ${result === 'B' ? 'border-indigo-500 bg-indigo-500/10' : result === 'A' ? 'border-slate-700 opacity-50 bg-slate-800' : 'border-slate-600 bg-slate-800 hover:border-indigo-400 hover:shadow-indigo-500/20'}
                        `}
                    >
                        <div className="absolute top-4 left-4 text-4xl font-black text-slate-700 group-hover:text-indigo-500/30 transition-colors">B</div>
                        <p className="text-xl font-medium text-center text-white z-10">{scenario.optionB}</p>

                         {result === 'B' && (
                            <div className="mt-4 pt-4 border-t border-indigo-500/30 animate-fade-in">
                                <p className="text-indigo-300 text-sm italic">"{scenario.consequenceB}"</p>
                            </div>
                        )}
                    </div>
                </div>

                {result && (
                    <button 
                        onClick={loadScenario}
                        className="mt-6 bg-slate-700 hover:bg-slate-600 text-white font-bold py-3 px-8 rounded-full transition-all animate-bounce-short"
                    >
                        {t.next}
                    </button>
                )}
            </div>
        ) : (
            <div className="text-red-500">{t.error}</div>
        )}
    </div>
  );
};

export default DilemmaGame;

import React, { useState, useEffect, useRef } from 'react';
import { LadderChallenge } from '../types';
import { generateLadderChallenge, validateLadderStep, getLadderHint } from '../services/geminiService';

interface Step {
    word: string;
    emoji: string;
}

const LadderGame: React.FC = () => {
    const [challenge, setChallenge] = useState<LadderChallenge | null>(null);
    const [steps, setSteps] = useState<Step[]>([]);
    const [inputValue, setInputValue] = useState('');
    const [loading, setLoading] = useState(false);
    const [validating, setValidating] = useState(false);
    const [feedback, setFeedback] = useState<string | null>(null);
    const [proximity, setProximity] = useState<number | null>(null); // 0-100
    const [won, setWon] = useState(false);
    const [quotaError, setQuotaError] = useState(false);

    // Hint State
    const [hintLoading, setHintLoading] = useState(false);
    const [activeHint, setActiveHint] = useState<{word: string, reason: string} | null>(null);

    const messagesEndRef = useRef<HTMLDivElement>(null);

    // Localization
    const isPt = typeof navigator !== 'undefined' ? navigator.language.startsWith('pt') : true;
    const t = {
        title: isPt ? "Ponte Semântica" : "Semantic Bridge",
        desc: isPt ? "Conecte as palavras usando associações." : "Connect the words using associations.",
        start: isPt ? "Início" : "Start",
        target: isPt ? "Alvo" : "Target",
        placeholder: isPt ? "Digite a próxima associação..." : "Type the next association...",
        submit: isPt ? "Conectar" : "Connect",
        loading: isPt ? "Gerando desafio..." : "Generating challenge...",
        checking: isPt ? "Verificando..." : "Checking...",
        win: isPt ? "Você completou a ponte!" : "You built the bridge!",
        next: isPt ? "Próximo Desafio" : "Next Challenge",
        steps: isPt ? "Passos:" : "Steps:",
        error: isPt ? "Erro ao conectar" : "Connection failed",
        quotaMsg: isPt ? "Limite diário da API atingido!" : "Daily API quota exceeded!",
        hintBtn: isPt ? "Pedir Dica" : "Get Hint",
        hintLoading: isPt ? "Pensando..." : "Thinking...",
        hot: isPt ? "QUENTE 🔥" : "HOT 🔥",
        warm: isPt ? "MORNO 😐" : "WARM 😐",
        cold: isPt ? "FRIO ❄️" : "COLD ❄️",
        proximity: isPt ? "Proximidade:" : "Proximity:"
    };

    const loadGame = async () => {
        setLoading(true);
        setWon(false);
        setSteps([]);
        setFeedback(null);
        setProximity(null);
        setActiveHint(null);
        setInputValue('');
        setQuotaError(false);
        try {
            const data = await generateLadderChallenge();
            if (data) {
                setChallenge(data);
                setSteps([{ word: data.startWord, emoji: data.startEmoji }]);
            }
        } catch (e: any) {
            if (e.name === 'QuotaExceededError') {
                setQuotaError(true);
            } else {
                console.error(e);
            }
        }
        setLoading(false);
    };

    useEffect(() => {
        loadGame();
    }, []);

    useEffect(() => {
        messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }, [steps, activeHint]);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!inputValue.trim() || !challenge || validating || won) return;

        setValidating(true);
        setFeedback(null);
        setProximity(null);
        setActiveHint(null);
        setQuotaError(false);

        const currentWord = steps[steps.length - 1].word;
        const guess = inputValue.trim();

        try {
            const result = await validateLadderStep(currentWord, challenge.endWord, guess);

            if (result.isValid) {
                setSteps(prev => [...prev, { word: guess, emoji: result.emoji || '🔗' }]);
                setInputValue('');
                setProximity(null);

                // Check win AFTER validation
                if (guess.toLowerCase() === challenge.endWord.toLowerCase()) {
                    setWon(true);
                }
            } else {
                setFeedback(result.message);
                if (result.proximity !== undefined) {
                    setProximity(result.proximity);
                }
            }
        } catch (e: any) {
             if (e.name === 'QuotaExceededError') {
                setQuotaError(true);
            } else {
                setFeedback("Error connecting to AI");
            }
        }

        setValidating(false);
    };

    const handleGetHint = async () => {
        if (!challenge || hintLoading || won) return;
        const currentWord = steps[steps.length - 1].word;

        setHintLoading(true);
        setActiveHint(null);
        setQuotaError(false);

        try {
            const hint = await getLadderHint(currentWord, challenge.endWord);
            if (hint) {
                setActiveHint(hint);
            }
        } catch (e: any) {
            if (e.name === 'QuotaExceededError') {
                setQuotaError(true);
            }
        }
        setHintLoading(false);
    };

    const getProximityColor = (val: number) => {
        if (val < 25) return 'text-blue-300';
        if (val < 60) return 'text-yellow-300';
        return 'text-red-400';
    };

    const getProximityText = (val: number) => {
        if (val < 25) return t.cold;
        if (val < 60) return t.warm;
        return t.hot;
    };

    if (quotaError) {
        return (
          <div className="flex flex-col items-center justify-center min-h-[60vh] max-w-md mx-auto p-8 animate-fade-in text-center">
               <div className="text-6xl mb-4">🛑</div>
               <h2 className="text-2xl font-bold text-red-400 mb-2">{t.quotaMsg}</h2>
          </div>
        )
    }

    return (
        <div className="flex flex-col items-center h-full max-w-2xl mx-auto p-4 animate-fade-in">
            <div className="text-center mb-6">
                <h2 className="text-3xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-emerald-400 to-teal-500">
                    {t.title}
                </h2>
                <p className="text-slate-400 text-sm mt-1">{t.desc}</p>
            </div>

            {loading ? (
                <div className="flex flex-col items-center py-12">
                    <div className="w-12 h-12 border-4 border-emerald-500 border-t-transparent rounded-full animate-spin"></div>
                    <p className="mt-4 text-emerald-300 animate-pulse">{t.loading}</p>
                </div>
            ) : challenge ? (
                <div className="w-full flex flex-col gap-4">

                    {/* Target Display */}
                    <div className="bg-slate-800/80 rounded-xl p-4 border border-slate-700 flex justify-between items-center sticky top-0 z-10 shadow-lg backdrop-blur">
                        <div className="flex flex-col items-center opacity-50">
                             <span className="text-2xl">{challenge.startEmoji}</span>
                             <span className="text-xs text-slate-400">{t.start}</span>
                             <span className="font-bold text-slate-300 line-through decoration-slate-500">{challenge.startWord}</span>
                        </div>

                        <div className="h-0.5 flex-1 bg-slate-700 mx-4 relative">
                            <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 text-slate-500 text-xs bg-slate-800 px-2">
                                {steps.length - 1} {t.steps}
                            </div>
                        </div>

                        <div className="flex flex-col items-center">
                             <span className="text-2xl animate-bounce-slow">{challenge.endEmoji}</span>
                             <span className="text-xs text-emerald-400 font-bold">{t.target}</span>
                             <span className="font-bold text-white text-lg">{challenge.endWord}</span>
                        </div>
                    </div>

                    {/* The Bridge (List of Steps) */}
                    <div className="flex flex-col gap-2 min-h-[300px] pb-40">
                        {steps.map((step, idx) => (
                            <div key={idx} className="flex flex-col items-center">
                                {idx > 0 && <div className="h-6 w-0.5 bg-slate-600 my-1"></div>}
                                <div className={`px-6 py-3 rounded-full border-2 text-lg font-bold flex items-center gap-3 shadow-lg w-full max-w-xs justify-center animate-fade-in
                                    ${idx === steps.length - 1 && !won ? 'bg-emerald-500/20 border-emerald-500 text-white' : 'bg-slate-700 border-slate-600 text-slate-300'}
                                    ${step.word === challenge.endWord ? 'bg-gradient-to-r from-yellow-500 to-amber-500 border-yellow-300 text-black scale-110' : ''}
                                `}>
                                    <span>{step.emoji}</span>
                                    <span>{step.word}</span>
                                </div>
                            </div>
                        ))}

                        {/* Hint Display */}
                        {activeHint && (
                            <div className="bg-blue-500/10 border border-blue-500/50 rounded-lg p-4 mx-auto max-w-sm text-center animate-fade-in my-4">
                                <p className="text-xs text-blue-300 uppercase font-bold mb-1">💡 DICA / HINT</p>
                                <p className="text-white text-lg font-bold mb-1">{activeHint.word}</p>
                                <p className="text-slate-400 text-sm italic">"{activeHint.reason}"</p>
                                <button 
                                    onClick={() => setInputValue(activeHint.word)} 
                                    className="mt-2 text-xs bg-blue-600 hover:bg-blue-500 text-white px-3 py-1 rounded"
                                >
                                    Usar / Use
                                </button>
                            </div>
                        )}

                        <div ref={messagesEndRef} />
                    </div>

                    {/* Input Area */}
                    <div className="fixed bottom-0 left-0 right-0 p-4 bg-gradient-to-t from-[#0f172a] via-[#0f172a] to-transparent z-20">
                        <div className="max-w-2xl mx-auto">
                            {won ? (
                                <button 
                                    onClick={loadGame}
                                    className="w-full bg-emerald-500 hover:bg-emerald-400 text-white font-bold py-4 rounded-xl shadow-lg shadow-emerald-900/50 animate-bounce-short"
                                >
                                    {t.win} - {t.next}
                                </button>
                            ) : (
                                <div>
                                    {/* Feedback Area */}
                                    {(feedback || proximity !== null) && (
                                        <div className="mb-3 bg-slate-800 rounded-lg p-3 flex items-center justify-between border border-slate-700 animate-fade-in">
                                            <span className="text-slate-300 text-sm flex-1 mr-2">{feedback}</span>
                                            {proximity !== null && (
                                                <div className="flex items-center gap-2 bg-slate-900 px-3 py-1 rounded">
                                                    <span className={`font-bold text-sm ${getProximityColor(proximity)}`}>
                                                        {getProximityText(proximity)}
                                                    </span>
                                                    <div className="w-16 h-2 bg-slate-700 rounded-full overflow-hidden">
                                                        <div 
                                                            className={`h-full ${proximity < 25 ? 'bg-blue-500' : proximity < 60 ? 'bg-yellow-500' : 'bg-red-500'}`} 
                                                            style={{ width: `${proximity}%` }}
                                                        />
                                                    </div>
                                                </div>
                                            )}
                                        </div>
                                    )}

                                    <form onSubmit={handleSubmit} className="relative">
                                        <input 
                                            type="text"
                                            value={inputValue}
                                            onChange={(e) => setInputValue(e.target.value)}
                                            placeholder={t.placeholder}
                                            disabled={validating}
                                            className="w-full bg-slate-800 border-2 border-slate-600 focus:border-emerald-500 text-white pl-4 pr-32 py-4 rounded-xl shadow-2xl focus:outline-none transition-colors"
                                            autoFocus
                                        />

                                        <div className="absolute right-2 top-2 bottom-2 flex gap-2">
                                            {!validating && (
                                                <button
                                                    type="button"
                                                    onClick={handleGetHint}
                                                    disabled={hintLoading}
                                                    className="bg-slate-700 hover:bg-slate-600 text-blue-300 px-3 rounded-lg font-bold text-lg disabled:opacity-50 transition-colors"
                                                    title={t.hintBtn}
                                                >
                                                    {hintLoading ? '...' : '💡'}
                                                </button>
                                            )}

                                            <button 
                                                type="submit" 
                                                disabled={!inputValue.trim() || validating}
                                                className="bg-emerald-600 hover:bg-emerald-500 text-white px-6 rounded-lg font-bold disabled:opacity-50 disabled:cursor-not-allowed transition-all"
                                            >
                                                {validating ? <div className="w-5 h-5 border-2 border-white/50 border-t-white rounded-full animate-spin"></div> : '➜'}
                                            </button>
                                        </div>
                                    </form>
                                </div>
                            )}
                        </div>
                    </div>

                </div>
            ) : (
                <div className="text-red-400 text-center">{t.error}</div>
            )}
        </div>
    );
};

export default LadderGame;

import React, { useState, useEffect, useRef } from 'react';
import { CipherChallenge } from '../types';
import { generateCipherChallengeBatch } from '../services/geminiService';

const CipherGame: React.FC = () => {
    const [challenge, setChallenge] = useState<CipherChallenge | null>(null);
    const [inputValue, setInputValue] = useState('');
    const [loading, setLoading] = useState(false);
    const [status, setStatus] = useState<'IDLE' | 'SUCCESS' | 'FAIL'>('IDLE');
    const [quotaError, setQuotaError] = useState(false);
    const [showRule, setShowRule] = useState(false);

    // Queue
    const [queue, setQueue] = useState<CipherChallenge[]>([]);
    const queueRef = useRef<CipherChallenge[]>([]);

    const [history, setHistory] = useState<string[]>(() => {
        if (typeof localStorage !== 'undefined') {
            const saved = localStorage.getItem('cipher_history');
            return saved ? JSON.parse(saved) : [];
        }
        return [];
    });

    useEffect(() => {
        localStorage.setItem('cipher_history', JSON.stringify(history));
    }, [history]);

    useEffect(() => {
        queueRef.current = queue;
    }, [queue]);

    const isPt = typeof navigator !== 'undefined' ? navigator.language.startsWith('pt') : true;
    const t = {
        title: isPt ? "Decodificador Críptico" : "Cryptic Decoder",
        desc: isPt ? "A IA bagunçou a frase. Use a lógica para consertar." : "AI messed up the phrase. Use logic to fix it.",
        loading: isPt ? "Encriptando dados..." : "Encrypting data...",
        category: isPt ? "Categoria:" : "Category:",
        rule: isPt ? "Regra de Encriptação:" : "Encryption Rule:",
        revealRule: isPt ? "Revelar Regra (Dica)" : "Reveal Rule (Hint)",
        placeholder: isPt ? "Digite a frase original..." : "Type original phrase...",
        submit: isPt ? "Decodificar" : "Decode",
        next: isPt ? "Próximo Arquivo" : "Next File",
        success: isPt ? "Acesso Concedido!" : "Access Granted!",
        fail: isPt ? "Acesso Negado." : "Access Denied.",
        giveUp: isPt ? "Desistir" : "Give Up",
        was: isPt ? "A frase era:" : "The phrase was:",
        quotaMsg: isPt ? "Limite diário da API atingido!" : "Daily API quota exceeded!",
        resetHistory: isPt ? "Limpar Histórico" : "Clear History"
    };

    const loadGame = async (currentHistory: string[] = history) => {
        setLoading(true);
        setStatus('IDLE');
        setInputValue('');
        setShowRule(false);
        setQuotaError(false);
        setChallenge(null);

        // 1. Check Queue
        if (queueRef.current.length > 0) {
            const next = queueRef.current[0];
            setChallenge(next);
            setQueue(prev => prev.slice(1));
            setLoading(false);
            return;
        }

        try {
            const batch = await generateCipherChallengeBatch(currentHistory);

            if (batch && batch.length > 0) {
                // Filter dupes locally
                const validBatch = batch.filter(c => !currentHistory.includes(c.original));
                if (validBatch.length > 0) {
                    setChallenge(validBatch[0]);
                    setQueue(validBatch.slice(1));
                } else {
                     // retry logic simplified
                }
            }
        } catch (e: any) {
             if (e.name === 'QuotaExceededError') {
                setQuotaError(true);
            } else {
                console.error(e);
            }
        }
        setLoading(false);
    };

    useEffect(() => {
        loadGame(history);
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    const normalize = (str: string) => str.toLowerCase().replace(/[^a-z0-9]/g, '');

    const addToHistory = (item: string) => {
        setHistory(prev => {
            if (!prev.includes(item)) {
                return [...prev, item];
            }
            return prev;
        });
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (!challenge) return;

        const guess = normalize(inputValue);
        const answer = normalize(challenge.original);

        if (guess === answer) {
            setStatus('SUCCESS');
            addToHistory(challenge.original);
        } else {
            setStatus('FAIL');
        }
    };

    const handleGiveUp = () => {
        if (!challenge) return;
        setInputValue(challenge.original);
        setStatus('FAIL');
        addToHistory(challenge.original);
    }

    const handleNext = () => {
        loadGame(history);
    }

    const clearHistory = () => {
        setHistory([]);
        localStorage.removeItem('cipher_history');
        window.location.reload();
    }

    if (quotaError) {
        return (
          <div className="flex flex-col items-center justify-center min-h-[60vh] max-w-md mx-auto p-8 animate-fade-in text-center font-mono text-green-500">
               <div className="text-6xl mb-4">🛑</div>
               <h2 className="text-2xl font-bold text-red-500 mb-2">{t.quotaMsg}</h2>
          </div>
        )
    }

    return (
        <div className="flex flex-col items-center h-full max-w-3xl mx-auto p-6 animate-fade-in font-mono relative">

            <button onClick={clearHistory} className="absolute top-2 right-4 text-[10px] text-green-500/50 hover:text-green-400 uppercase tracking-widest">
                {t.resetHistory}
            </button>

            <div className="text-center mb-8">
                <h2 className="text-3xl font-bold text-green-500 tracking-wider uppercase border-b border-green-500/30 pb-2 inline-block">
                    {t.title}
                </h2>
                <p className="text-green-500/60 text-sm mt-2">{t.desc}</p>
            </div>

            {loading ? (
                <div className="flex flex-col items-center py-12">
                     <div className="font-mono text-green-500 animate-pulse text-xl">
                        {t.loading}
                        <br/>
                        <span className="text-xs">Processing...</span>
                     </div>
                </div>
            ) : challenge ? (
                <div className="w-full bg-black border border-green-500/50 p-6 rounded-sm shadow-[0_0_15px_rgba(34,197,94,0.2)]">

                    <div className="flex justify-between items-center border-b border-green-500/30 pb-4 mb-6">
                        <span className="text-xs text-green-500/50 uppercase tracking-widest">{t.category} <span className="text-green-400">{challenge.category}</span></span>
                        <div className="flex gap-2">
                             <div className="w-3 h-3 rounded-full bg-red-500/50"></div>
                             <div className="w-3 h-3 rounded-full bg-yellow-500/50"></div>
                             <div className="w-3 h-3 rounded-full bg-green-500/50"></div>
                        </div>
                    </div>

                    <div className="bg-green-900/10 p-6 mb-6 rounded border-l-4 border-green-500">
                        <p className="text-2xl md:text-3xl font-bold text-green-300 font-mono break-words leading-relaxed select-none tracking-widest">
                            {challenge.encrypted}
                        </p>
                    </div>

                    <div className="mb-6 flex justify-center">
                        {showRule ? (
                            <div className="bg-green-500/10 px-4 py-2 rounded border border-green-500/30 text-green-400 text-sm animate-fade-in">
                                <span className="font-bold mr-2">root@system:~$</span>
                                {t.rule} <span className="text-white bg-green-900/50 px-2 py-0.5 rounded">{challenge.rule}</span>
                            </div>
                        ) : (
                            <button 
                                onClick={() => setShowRule(true)}
                                className="text-xs text-green-500/70 hover:text-green-400 border border-green-500/30 px-3 py-1 rounded hover:bg-green-500/10 transition-colors"
                            >
                                [ {t.revealRule} ]
                            </button>
                        )}
                    </div>

                    <form onSubmit={handleSubmit} className="flex flex-col gap-4">
                        <div className="relative group">
                            <span className="absolute left-4 top-1/2 -translate-y-1/2 text-green-500/50 font-bold">{">"}</span>
                            <input 
                                type="text"
                                value={inputValue}
                                onChange={(e) => {
                                    setInputValue(e.target.value);
                                    if (status !== 'IDLE') setStatus('IDLE');
                                }}
                                disabled={status === 'SUCCESS'}
                                placeholder={t.placeholder}
                                className={`w-full bg-black border ${status === 'FAIL' ? 'border-red-500 text-red-400' : 'border-green-500/50 text-green-400'} rounded p-4 pl-8 focus:outline-none focus:border-green-400 focus:shadow-[0_0_10px_rgba(34,197,94,0.3)] transition-all font-mono text-lg`}
                                autoFocus
                            />
                        </div>

                        {status === 'SUCCESS' && (
                            <div className="text-center p-4 bg-green-500/20 border border-green-500 text-green-300 rounded animate-bounce-short">
                                {t.success}
                            </div>
                        )}

                        {status === 'FAIL' && inputValue.length > 0 && (
                             <div className="text-center text-red-400 text-sm font-bold animate-shake">
                                {t.fail}
                             </div>
                        )}

                        <div className="flex gap-3 justify-center mt-2">
                             {status === 'SUCCESS' ? (
                                <button 
                                    type="button"
                                    onClick={handleNext}
                                    className="bg-green-600 hover:bg-green-500 text-black font-bold py-3 px-8 rounded shadow-lg transition-transform hover:scale-105"
                                >
                                    {t.next}
                                </button>
                             ) : (
                                <>
                                    <button 
                                        type="button"
                                        onClick={handleGiveUp}
                                        className="text-green-500/50 hover:text-red-400 text-sm px-4 py-3"
                                    >
                                        {t.giveUp}
                                    </button>
                                    <button 
                                        type="submit"
                                        disabled={!inputValue.trim()}
