  const getAiStudio = () => {
      try {
          return (window as any).aistudio || (window.parent as any)?.aistudio;
      } catch (e) {
          return (window as any).aistudio;
      }
  };

  const checkAuth = async () => {
    setIsChecking(true);
    setAuthError(null);

