import React, { useState, useEffect, useRef } from 'react';
import { LadderChallenge } from '../types';
import { generateLadderChallenge, validateLadderStep, getLadderHint } from '../services/geminiService';

interface Step {
    word: string;
    emoji: string;
}

const LadderGame: React.FC = () => {
    const [challenge, setChallenge] = useState<LadderChallenge | null>(null);
    const [steps, setSteps] = useState<Step[]>([]);
    const [inputValue, setInputValue] = useState('');
    const [loading, setLoading] = useState(false);
    const [validating, setValidating] = useState(false);
    const [feedback, setFeedback] = useState<string | null>(null);
    const [proximity, setProximity] = useState<number | null>(null); // 0-100
    const [won, setWon] = useState(false);
    const [quotaError, setQuotaError] = useState(false);

    // Hint State
    const [hintLoading, setHintLoading] = useState(false);
    const [activeHint, setActiveHint] = useState<{word: string, reason: string} | null>(null);

    const messagesEndRef = useRef<HTMLDivElement>(null);

    // Localization
    const isPt = typeof navigator !== 'undefined' ? navigator.language.startsWith('pt') : true;
    const t = {
        title: isPt ? "Ponte Semântica" : "Semantic Bridge",
        desc: isPt ? "Conecte as palavras. Use pelo menos 2 degraus antes do alvo!" : "Connect the words. Use at least 2 steps before the target!",
        start: isPt ? "Início" : "Start",
        target: isPt ? "Alvo" : "Target",
        placeholder: isPt ? "Digite a próxima associação..." : "Type the next association...",
        submit: isPt ? "Conectar" : "Connect",
        loading: isPt ? "Gerando desafio..." : "Generating challenge...",
        checking: isPt ? "Verificando..." : "Checking...",
        win: isPt ? "Você completou a ponte!" : "You built the bridge!",
        next: isPt ? "Próximo Desafio" : "Next Challenge",
        steps: isPt ? "Passos:" : "Steps:",
        error: isPt ? "Erro ao conectar" : "Connection failed",
        quotaMsg: isPt ? "Limite diário da API atingido!" : "Daily API quota exceeded!",
        hintBtn: isPt ? "Pedir Dica" : "Get Hint",
        hintLoading: isPt ? "Pensando..." : "Thinking...",
        hot: isPt ? "QUENTE 🔥" : "HOT 🔥",
        warm: isPt ? "MORNO 😐" : "WARM 😐",
        cold: isPt ? "FRIO ❄️" : "COLD ❄️",
        proximity: isPt ? "Proximidade:" : "Proximity:",
        tooShort: isPt ? "A ponte está curta demais! Adicione pelo menos 2 passos intermediários primeiro." : "The bridge is too short! Add at least 2 intermediate steps first."
    };

    const loadGame = async () => {
        setLoading(true);
        setWon(false);
        setSteps([]);
        setFeedback(null);
        setProximity(null);
        setActiveHint(null);
        setInputValue('');
        setQuotaError(false);
        try {
            const data = await generateLadderChallenge();
            if (data) {
                setChallenge(data);
                setSteps([{ word: data.startWord, emoji: data.startEmoji }]);
            }
        } catch (e: any) {
            if (e.name === 'QuotaExceededError') {
                setQuotaError(true);
            } else {
                console.error(e);
            }
        }
        setLoading(false);
    };

    useEffect(() => {
        loadGame();
    }, []);

    useEffect(() => {
        messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }, [steps, activeHint]);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!inputValue.trim() || !challenge || validating || won) return;

        const guess = inputValue.trim();

        // Anti-skip logic: Require at least 2 intermediate steps (Start + Step 1 + Step 2 = 3 steps total)
        if (guess.toLowerCase() === challenge.endWord.toLowerCase() && steps.length < 3) {
            setFeedback(t.tooShort);
            setProximity(100);
            return;
        }

        setValidating(true);
        setFeedback(null);
        setProximity(null);
        setActiveHint(null);
        setQuotaError(false);

        const currentWord = steps[steps.length - 1].word;

        try {
            const result = await validateLadderStep(currentWord, challenge.endWord, guess);

            if (result.isValid) {
                setSteps(prev => [...prev, { word: guess, emoji: result.emoji || '🔗' }]);
                setInputValue('');
                setProximity(null);

                // Check win condition
                if (guess.toLowerCase() === challenge.endWord.toLowerCase()) {
                    setWon(true);
                }
            } else {
                setFeedback(result.message);
                if (result.proximity !== undefined) {
                    setProximity(result.proximity);
                }
            }
        } catch (e: any) {
             if (e.name === 'QuotaExceededError') {
                setQuotaError(true);
            } else {
                setFeedback("Error connecting to AI");
            }
        }

        setValidating(false);
    };

    const handleGetHint = async () => {
        if (!challenge || hintLoading || won) return;
        const currentWord = steps[steps.length - 1].word;

        setHintLoading(true);
        setActiveHint(null);
        setQuotaError(false);

        try {
            const hint = await getLadderHint(currentWord, challenge.endWord);
            if (hint) {
                setActiveHint(hint);
            }
        } catch (e: any) {
            if (e.name === 'QuotaExceededError') {
                setQuotaError(true);
            }
        }
        setHintLoading(false);
    };

    const getProximityColor = (val: number) => {
        if (val < 25) return 'text-blue-300';
        if (val < 60) return 'text-yellow-300';
        return 'text-red-400';
    };

    const getProximityText = (val: number) => {
        if (val < 25) return t.cold;
        if (val < 60) return t.warm;
        return t.hot;
    };

    if (quotaError) {
        return (
          <div className="flex flex-col items-center justify-center min-h-[60vh] max-w-md mx-auto p-8 animate-fade-in text-center">
               <div className="text-6xl mb-4">🛑</div>
               <h2 className="text-2xl font-bold text-red-400 mb-2">{t.quotaMsg}</h2>
          </div>
        )
    }

    return (
        <div className="flex flex-col items-center h-full max-w-2xl mx-auto p-4 animate-fade-in">
            <div className="text-center mb-6">
                <h2 className="text-3xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-emerald-400 to-teal-500">
                    {t.title}
                </h2>
                <p className="text-slate-400 text-sm mt-1">{t.desc}</p>
            </div>

            {loading ? (
                <div className="flex flex-col items-center py-12">
                    <div className="w-12 h-12 border-4 border-emerald-500 border-t-transparent rounded-full animate-spin"></div>
                    <p className="mt-4 text-emerald-300 animate-pulse">{t.loading}</p>
                </div>
            ) : challenge ? (
                <div className="w-full flex flex-col gap-4">

                    {/* Target Display */}
                    <div className="bg-slate-800/80 rounded-xl p-4 border border-slate-700 flex justify-between items-center sticky top-0 z-10 shadow-lg backdrop-blur">
                        <div className="flex flex-col items-center opacity-50">
                             <span className="text-2xl">{challenge.startEmoji}</span>
                             <span className="text-xs text-slate-400">{t.start}</span>
                             <span className="font-bold text-slate-300 line-through decoration-slate-500">{challenge.startWord}</span>
                        </div>

                        <div className="h-0.5 flex-1 bg-slate-700 mx-4 relative">
                            <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 text-slate-500 text-[10px] font-black bg-slate-800 px-2 uppercase tracking-tighter">
                                {steps.length - 1} {t.steps}
                            </div>
                        </div>

                        <div className="flex flex-col items-center">
                             <span className="text-2xl animate-bounce-slow">{challenge.endEmoji}</span>
                             <span className="text-xs text-emerald-400 font-bold">{t.target}</span>
                             <span className="font-bold text-white text-lg">{challenge.endWord}</span>
                        </div>
                    </div>

                    {/* The Bridge (List of Steps) */}
                    <div className="flex flex-col gap-2 min-h-[300px] pb-40">
                        {steps.map((step, idx) => (
                            <div key={idx} className="flex flex-col items-center">
                                {idx > 0 && <div className="h-6 w-0.5 bg-slate-600 my-1"></div>}
                                <div className={`px-6 py-3 rounded-full border-2 text-lg font-bold flex items-center gap-3 shadow-lg w-full max-w-xs justify-center animate-fade-in
                                    ${idx === steps.length - 1 && !won ? 'bg-emerald-500/20 border-emerald-500 text-white' : 'bg-slate-700 border-slate-600 text-slate-300'}
                                    ${step.word === challenge.endWord ? 'bg-gradient-to-r from-yellow-500 to-amber-500 border-yellow-300 text-black scale-110' : ''}
                                `}>
                                    <span>{step.emoji}</span>
                                    <span>{step.word}</span>
                                </div>
                            </div>
                        ))}

                        {/* Hint Display */}
                        {activeHint && (
                            <div className="bg-blue-500/10 border border-blue-500/50 rounded-lg p-4 mx-auto max-w-sm text-center animate-fade-in my-4">
                                <p className="text-xs text-blue-300 uppercase font-bold mb-1">💡 DICA / HINT</p>
                                <p className="text-white text-lg font-bold mb-1">{activeHint.word}</p>
                                <p className="text-slate-400 text-sm italic">"{activeHint.reason}"</p>
                                <button 
                                    onClick={() => setInputValue(activeHint.word)} 
                                    className="mt-2 text-xs bg-blue-600 hover:bg-blue-500 text-white px-3 py-1 rounded"
                                >
                                    Usar / Use
                                </button>
                            </div>
                        )}

                        <div ref={messagesEndRef} />
                    </div>

                    {/* Input Area */}
                    <div className="fixed bottom-0 left-0 right-0 p-4 bg-gradient-to-t from-[#0f172a] via-[#0f172a] to-transparent z-20">
                        <div className="max-w-2xl mx-auto">
                            {won ? (
                                <button 
                                    onClick={loadGame}
                                    className="w-full bg-emerald-500 hover:bg-emerald-400 text-white font-bold py-4 rounded-xl shadow-lg shadow-emerald-900/50 animate-bounce-short"
                                >
                                    {t.win} - {t.next}
                                </button>
                            ) : (
                                <div>
                                    {/* Feedback Area */}
                                    {(feedback || proximity !== null) && (
                                        <div className="mb-3 bg-slate-800 rounded-lg p-3 flex items-center justify-between border border-slate-700 animate-fade-in">
                                            <span className="text-slate-300 text-[11px] font-bold flex-1 mr-2 leading-tight uppercase tracking-tight">{feedback}</span>
                                            {proximity !== null && (
                                                <div className="flex items-center gap-2 bg-slate-900 px-3 py-1 rounded">
                                                    <span className={`font-bold text-[10px] uppercase ${getProximityColor(proximity)}`}>
                                                        {getProximityText(proximity)}
                                                    </span>
                                                    <div className="w-16 h-2 bg-slate-700 rounded-full overflow-hidden">
                                                        <div 
                                                            className={`h-full transition-all duration-500 ${proximity < 25 ? 'bg-blue-500' : proximity < 60 ? 'bg-yellow-500' : 'bg-red-500'}`} 
                                                            style={{ width: `${proximity}%` }}
                                                        />
                                                    </div>
                                                </div>
                                            )}
                                        </div>
                                    )}

                                    <form onSubmit={handleSubmit} className="relative">
                                        <input 
                                            type="text"
                                            value={inputValue}
                                            onChange={(e) => setInputValue(e.target.value)}
                                            placeholder={t.placeholder}
                                            disabled={validating}
                                            className="w-full bg-slate-800 border-2 border-slate-600 focus:border-emerald-500 text-white pl-4 pr-32 py-4 rounded-xl shadow-2xl focus:outline-none transition-colors"
                                            autoFocus
                                        />

                                        <div className="absolute right-2 top-2 bottom-2 flex gap-2">
                                            {!validating && (
                                                <button
                                                    type="button"
                                                    onClick={handleGetHint}
                                                    disabled={hintLoading}
                                                    className="bg-slate-700 hover:bg-slate-600 text-blue-300 px-3 rounded-lg font-bold text-lg disabled:opacity-50 transition-colors"
                                                    title={t.hintBtn}
                                                >
                                                    {hintLoading ? '...' : '💡'}
                                                </button>
                                            )}

                                            <button 
                                                type="submit" 
                                                disabled={!inputValue.trim() || validating}
                                                className="bg-emerald-600 hover:bg-emerald-500 text-white px-6 rounded-lg font-bold disabled:opacity-50 disabled:cursor-not-allowed transition-all"
                                            >
                                                {validating ? <div className="w-5 h-5 border-2 border-white/50 border-t-white rounded-full animate-spin"></div> : '➜'}
                                            </button>
                                        </div>
                                    </form>
                                </div>
                            )}
                        </div>
                    </div>

                </div>
            ) : (
                <div className="text-red-400 text-center">{t.error}</div>
            )}
        </div>
    );
};

export default LadderGame;

import React, { useState, useMemo, useEffect } from 'react';
import { GameType } from './types';
import AlchemyGame from './components/AlchemyGame';
import EmojiGame from './components/EmojiGame';
import DilemmaGame from './components/DilemmaGame';
import LadderGame from './components/LadderGame';
import CipherGame from './components/CipherGame';
import ArenaGame from './components/ArenaGame';

const App: React.FC = () => {
  const [activeGame, setActiveGame] = useState<GameType>(GameType.NONE);
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(false);
  const [isChecking, setIsChecking] = useState<boolean>(true);
  const [authError, setAuthError] = useState<string | null>(null);

  const isPt = typeof navigator !== 'undefined' ? navigator.language.startsWith('pt') : true;

  // Ultra-robust detection for AI Studio platform selector
  const getAiStudio = () => {
      try {
          // Check current window, then parent, then top to cover all iframe nesting scenarios
          const found = (window as any).aistudio || 
                        (window.parent as any)?.aistudio || 
                        (window.top as any)?.aistudio;
          return found;
      } catch (e) {
          // Fallback if cross-origin policy prevents parent/top access
          return (window as any).aistudio;
      }
  };

  const checkAuth = async () => {
    setIsChecking(true);
    setAuthError(null);

    // 1. Check if Key is already injected (Automatic bypass for production/manual deploys)
    if (process.env.API_KEY && process.env.API_KEY.length > 5) {
      setIsAuthenticated(true);
      setIsChecking(false);
      return;
    }

    // 2. Check for AI Studio platform selector presence
    const aiStudio = getAiStudio();
    if (aiStudio) {
      try {
        const hasKey = await aiStudio.hasSelectedApiKey();
        setIsAuthenticated(hasKey);
      } catch (e) {
        console.error("Auth check failed:", e);
      }
    }
    setIsChecking(false);
  };

  useEffect(() => {
    checkAuth();
  }, []);

  const handleLogin = async () => {
    const aiStudio = getAiStudio();

    if (aiStudio) {
      try {
        await aiStudio.openSelectKey();
        // Assume success to proceed immediately as per platform rules for better UX
        setIsAuthenticated(true);
      } catch (e) {
        setAuthError(isPt ? "Ocorreu um erro ao abrir o seletor oficial." : "An error occurred opening the official selector.");
      }
    } else {
        setAuthError(isPt 
            ? "O seletor oficial do Google não foi detectado neste ambiente. Se você é o dono deste site, configure a variável 'API_KEY' nas configurações do seu projeto (Vercel/GitHub/Netlify) para que todos possam jogar." 
            : "Official Google selector not detected. If you are the owner, set 'API_KEY' in your project settings (Vercel/GitHub/Netlify) to enable play for everyone.");
    }
  };

  if (isChecking) {
    return (
      <div className="min-h-screen bg-[#0f172a] flex items-center justify-center">
        <div className="flex flex-col items-center gap-4">
            <div className="w-12 h-12 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
            <p className="text-indigo-400 text-xs font-bold uppercase tracking-widest animate-pulse">
                {isPt ? "Sincronizando..." : "Synchronizing..."}
            </p>
        </div>
      </div>
    );
  }

  // LOGIN SCREEN
  if (!isAuthenticated) {
    return (
      <div className="min-h-screen bg-[#0f172a] text-white flex flex-col items-center justify-center p-6 relative overflow-hidden">
        <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-indigo-500/10 via-transparent to-transparent opacity-40"></div>
        <div className="absolute top-0 left-0 w-full h-full bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-20 pointer-events-none"></div>

        <div className="max-w-md w-full text-center relative z-10 space-y-10 animate-fade-in">
          <div className="flex flex-col items-center">
              <div className="w-24 h-24 rounded-3xl bg-gradient-to-br from-indigo-500 to-purple-600 shadow-2xl shadow-indigo-500/30 flex items-center justify-center text-5xl mb-6 animate-bounce-slow">
                🌌
              </div>
              <h1 className="text-5xl font-black tracking-tighter mb-2 bg-clip-text text-transparent bg-gradient-to-b from-white to-slate-400">
                Nebula Arcade
              </h1>
              <p className="text-slate-400 text-lg">
                {isPt ? "Diversão infinita movida por IA." : "Infinite AI-powered fun."}
              </p>
          </div>

          <div className="bg-slate-900/60 backdrop-blur-3xl border border-slate-800 p-8 rounded-3xl shadow-2xl space-y-6">
            <div className="space-y-3">
                <p className="text-sm font-medium text-slate-300">
                    {isPt ? "Conecte-se para liberar o acesso" : "Connect to unlock access"}
                </p>
                {authError && (
                    <div className="p-4 bg-red-500/10 border border-red-500/20 rounded-xl text-[11px] text-red-400 leading-relaxed animate-shake text-left font-bold uppercase tracking-tighter">
                        {authError}
                    </div>
                )}
            </div>

            <div className="flex flex-col gap-3">
                <button 
                  onClick={handleLogin}
                  className="w-full bg-white text-black font-black py-4 px-8 rounded-2xl hover:bg-slate-200 transition-all transform active:scale-95 shadow-xl flex items-center justify-center gap-3 text-lg"
                >
                  <span className="text-xl">✨</span>
                  {isPt ? "Conectar Gemini" : "Connect Gemini"}
                </button>

                <button 
                  onClick={checkAuth}
                  className="w-full bg-slate-800/50 hover:bg-slate-800 text-slate-400 font-bold py-3 px-8 rounded-2xl border border-slate-700 transition-all text-sm"
                >
                  {isPt ? "Tentar Novamente" : "Try Again"}
                </button>
            </div>
          </div>

          <p className="text-[10px] text-slate-600 leading-relaxed max-w-xs mx-auto font-bold uppercase tracking-widest">
              {isPt 
                ? "Ambiente seguro. Sua chave não é armazenada pelo site." 
                : "Secure environment. Your key is not stored by the site."}
          </p>
        </div>
      </div>
    );
  }

  // ARCADE MAIN UI
  const renderGame = () => {
    switch (activeGame) {
      case GameType.ALCHEMY: return <AlchemyGame />;
      case GameType.EMOJI: return <EmojiGame />;
      case GameType.DILEMMA: return <DilemmaGame />;
      case GameType.LADDER: return <LadderGame />;
      case GameType.CIPHER: return <CipherGame />;
      case GameType.ARENA: return <ArenaGame />;
      default: return <HomeGrid onSelect={setActiveGame} />;
    }
  };

  return (
    <div className="min-h-screen bg-[#0f172a] text-slate-100 flex flex-col">
      <header className="sticky top-0 z-50 backdrop-blur-md bg-[#0f172a]/80 border-b border-slate-800">
        <div className="max-w-6xl mx-auto px-4 h-16 flex items-center justify-between">
            <div 
                className="flex items-center gap-2 cursor-pointer group"
                onClick={() => setActiveGame(GameType.NONE)}
            >
                <div className="w-8 h-8 rounded-lg bg-gradient-to-br from-indigo-500 to-purple-600 flex items-center justify-center shadow-lg group-hover:rotate-12 transition-transform">
                    <span className="text-lg">🌌</span>
                </div>
                <h1 className="text-xl font-bold tracking-tight text-white group-hover:text-purple-300 transition-colors">Nebula Arcade</h1>
            </div>

            <div className="flex items-center gap-4">
                <div className="flex items-center gap-2 px-3 py-1.5 rounded-full text-[10px] font-bold uppercase tracking-widest bg-emerald-500/10 border border-emerald-500/30 text-emerald-400">
                    <span className="w-2 h-2 rounded-full bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.8)]"></span>
                    API ATIVA
                </div>

                {activeGame !== GameType.NONE && (
                    <button 
                        onClick={() => setActiveGame(GameType.NONE)}
                        className="text-sm font-medium text-slate-400 hover:text-white transition-colors bg-slate-800/50 px-3 py-1.5 rounded-md hover:bg-slate-700 border border-slate-700"
                    >
                        ← {isPt ? 'Início' : 'Home'}
                    </button>
                )}
            </div>
        </div>
      </header>

      <main className="flex-1 overflow-hidden relative">
        <div className="absolute inset-0 bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-20 pointer-events-none"></div>
        <div className="h-full w-full overflow-y-auto">
            {renderGame()}
        </div>
      </main>

      <footer className="py-6 border-t border-slate-800 text-center text-slate-500 text-xs relative z-10 bg-[#0f172a]">
        <p>Nebula Arcade &copy; 2025 • Gemini Powered • 🌌</p>
      </footer>
    </div>
  );
};

interface HomeGridProps {
  onSelect: (game: GameType) => void;
}

const HomeGrid: React.FC<HomeGridProps> = ({ onSelect }) => {
  const isPt = typeof navigator !== 'undefined' ? navigator.language.startsWith('pt') : true;
  const [search, setSearch] = useState('');

  const gamesList = useMemo(() => [
    {
        id: GameType.ALCHEMY,
        title: isPt ? "Alquimia Neural" : "Neural Alchemy",
        description: isPt ? "Combine elementos para criar o universo." : "Combine elements to create the universe.",
        icon: "⚗️",
        color: "from-blue-500 to-cyan-400",
        tags: isPt ? ["Criatividade", "Alquimia"] : ["Creativity", "Alchemy"]
    },
    {
        id: GameType.EMOJI,
        title: isPt ? "Detetive de Emojis" : "Emoji Detective",
        description: isPt ? "Adivinhe a obra baseada nos emojis." : "Guess the work based on emojis.",
        icon: "🕵️‍♂️",
        color: "from-yellow-400 to-orange-500",
        tags: isPt ? ["Quiz", "Cultura Pop"] : ["Quiz", "Pop Culture"]
    },
    {
        id: GameType.DILEMMA,
        title: isPt ? "Dilema Absurdo" : "Absurd Dilemma",
        description: isPt ? "Escolhas morais impossíveis e hilárias." : "Impossible and hilarious moral choices.",
        icon: "⚖️",
        color: "from-pink-500 to-rose-500",
        tags: isPt ? ["Humor", "Social"] : ["Humor", "Social"]
    },
    {
        id: GameType.LADDER,
        title: isPt ? "Ponte Semântica" : "Semantic Bridge",
        description: isPt ? "Conecte palavras distantes degrau por degrau." : "Connect distant words step by step.",
        icon: "🪜",
        color: "from-amber-700 to-orange-800",
        tags: isPt ? ["Lógica", "Palavras"] : ["Logic", "Words"]
    },
    {
        id: GameType.CIPHER,
        title: isPt ? "Decodificador" : "Cipher Decoder",
        description: isPt ? "Descifre frases famosas bagunçadas pela IA." : "Decipher famous quotes messed up by AI.",
        icon: "📟",
        color: "from-green-600 to-emerald-600",
        tags: isPt ? ["Mistério", "Cyber"] : ["Mystery", "Cyber"],
        isNew: true
    },
    {
        id: GameType.ARENA,
        title: isPt ? "Arena de Sobrevivência" : "Survival Arena",
        description: isPt ? "Enfrente feras reais e mitológicas com estratégia." : "Face real and mythological beasts with strategy.",
        icon: "👹",
        color: "from-red-600 to-orange-600",
        tags: isPt ? ["RPG", "Estratégia"] : ["RPG", "Strategy"],
        isNew: true
    }
  ], [isPt]);

  const filteredGames = useMemo(() => {
    const q = search.toLowerCase();
    if (!q) return gamesList;
    return gamesList.filter(g => 
        g.title.toLowerCase().includes(q) || 
        g.tags.some(t => t.toLowerCase().includes(q))
    );
  }, [search, gamesList]);

  return (
    <div className="max-w-6xl mx-auto px-4 py-12 animate-fade-in">
        <div className="text-center mb-12">
            <h2 className="text-4xl md:text-6xl font-black mb-4 bg-clip-text text-transparent bg-gradient-to-b from-white to-slate-400">
